@lru_cache(maxsize=1)
def _rows():return {r['case']['key']:r for r in json.loads(FIXTURE.read_text(encoding='utf-8'))['rows']}
def expected(case):return json.loads(json.dumps(_rows()[case['key']]['expected']))
def production(case):
    from PyFLASH import association_coefficients,association_correlations
    module=association_coefficients if case['kind']=='coefficients' else association_correlations
    request=json.loads(json.dumps(case['request']))
    if case['form']=='tuple':request=tuple(request)
    if case['form']=='mapping-items':request=dict(request)
    try:return {'normalized':module.normalize_specs(request)}
    except ValueError:return {'error_type':'ValueError'}
def capability(case):return 'PyFLASH.association_'+case['kind']+'.normalize_specs'
def check_identity():
    fixture=json.loads(FIXTURE.read_text(encoding='utf-8'))
    if hashlib.sha256(Path(__file__).read_bytes()).hexdigest()!=fixture['reference_code_sha256']:raise ValueError('Association request reference changed')
    if cases()!=[r['case'] for r in fixture['rows']]:raise ValueError('Association request definitions changed')
    return fixture
